// Writes tests/fixtures/old-versions/v2-assembly.3dba with the code as it was at the last commit of assembly Schema 2 (fa2ee17).
// It only writes when WRITE_FIXTURE=1; the file is a fixture and is never to be regenerated by a later version (README there).
// Run (before assembly Schema 3 exists): $env:WRITE_FIXTURE='1'; npx vitest run --config spikes/occt-gaps/vitest.config.ts spikes/occt-gaps/phase3b-fixture-v2-assembly.test.ts
import { writeFileSync } from 'node:fs';
import { expect, it } from 'vitest';
import { applyAssemblyCommand, ASSEMBLY_SCHEMA_VERSION, axisAngle, createEmptyAssembly, type Mate } from '@3db/model';
import { writeAssemblyFile } from '@3db/io';

it.skipIf(process.env.WRITE_FIXTURE !== '1')('writes the version-2 assembly sample', async () => {
  expect(ASSEMBLY_SCHEMA_VERSION).toBe(2);
  const face = (name: string) => ({ kind: 'face' as const, name });
  let doc = createEmptyAssembly();
  const insert = (id: string, file: string, path: string | null, instance: number, fixed: boolean, position: [number, number, number], rotation: [number, number, number, number]) => {
    doc = applyAssemblyCommand(doc, { type: 'insertComponent', ...(path ? { file: { id: file, path } } : {}), component: { id, file, instance, fixed, placement: { position, rotation } } });
  };
  insert('comp1', 'file1', '../定位板.3dbx', 1, true, [0, 0, 0], [0, 0, 0, 1]);
  insert('comp2', 'file2', '../零件/削邊銷.3dbx', 1, false, [-30, 30, 0], axisAngle([0.6, 0.8, 0], 0.25));
  insert('comp3', 'file2', null, 2, false, [30, 30, 0], [0, 0, 0, 1]);
  const mate = (n: number, type: Mate['type'], aName: string, bName: string, align: Mate['align']) => {
    doc = applyAssemblyCommand(doc, {
      type: 'insertMate',
      mate: { id: `mate${n}`, name: `${type === 'concentric' ? '同軸心' : '重合'}${n}`, type, a: { component: 'comp1', ref: face(aName) }, b: { component: 'comp2', ref: face(bName) }, align, suppressed: false },
    });
  };
  mate(1, 'concentric', 'cut1:side:sketch2.ci6', 'revolve1:side:sketch1.l3#1', 'aligned');
  mate(2, 'coincident', 'extrude1:cap:end', 'revolve1:side:sketch1.l4', 'antiAligned');
  writeFileSync(new URL('../../tests/fixtures/old-versions/v2-assembly.3dba', import.meta.url), await writeAssemblyFile(doc));
});

// Schema 3 sample (3b-1): a sub-assembly used twice, a mate with a component path, a flag on a component. Written by the Schema 4 code with schemaVersion set to 3:
// Schema 4 only adds the optional `patterns`, so a Schema 3 file is exactly this text (it was not written by the Schema 3 code itself).
it.skipIf(process.env.WRITE_FIXTURE_V3 !== '1')('writes the version-3 assembly sample', async () => {
  const face = (name: string) => ({ kind: 'face' as const, name });
  let doc = createEmptyAssembly();
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', file: { id: 'file1', path: '組件/定位組.3dba' }, component: { id: 'comp1', file: 'file1', instance: 1, fixed: true, placement: { position: [0, 0, 0], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', component: { id: 'comp2', file: 'file1', instance: 2, fixed: false, placement: { position: [126, 4, -3], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, {
    type: 'insertMate',
    mate: { id: 'mate1', name: '重合1', type: 'coincident', a: { component: 'comp1', path: ['p1'], ref: face('extrude1:cap:end') }, b: { component: 'comp2', path: ['p1'], ref: face('extrude1:cap:end') }, align: 'aligned', suppressed: false },
  });
  doc = applyAssemblyCommand(doc, { type: 'setComponentState', componentIds: ['comp2'], state: 'transparent', value: true });
  writeFileSync(new URL('../../tests/fixtures/old-versions/v3-assembly.3dba', import.meta.url), await writeAssemblyFile({ ...doc, schemaVersion: 3 }));
});

// Schema 4 sample (3b-2): a component with a linear pattern and a mirror. Written by the Schema 5 code with schemaVersion set to 4: Schema 5 only adds the
// optional `explosion`, so a Schema 4 file is exactly this text (it was not written by the Schema 4 code itself).
it.skipIf(process.env.WRITE_FIXTURE_V4 !== '1')('writes the version-4 assembly sample', async () => {
  let doc = createEmptyAssembly();
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', file: { id: 'file1', path: '../定位板.3dbx' }, component: { id: 'comp1', file: 'file1', instance: 1, fixed: true, placement: { position: [0, 0, 0], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', file: { id: 'file2', path: '../零件/削邊銷.3dbx' }, component: { id: 'comp2', file: 'file2', instance: 1, fixed: false, placement: { position: [-40, 15, 0], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, { type: 'insertPattern', pattern: { id: 'pattern1', name: '線性複製排列1', kind: 'linear', seed: 'comp2', axis1: { kind: 'axis', axis: 'x' }, count1: 3, spacing1: '40', skip: ['3'] } });
  doc = applyAssemblyCommand(doc, { type: 'insertPattern', pattern: { id: 'pattern2', name: '鏡射零組件1', kind: 'mirror', seed: 'comp2', plane: 'plane:right' } });
  writeFileSync(new URL('../../tests/fixtures/old-versions/v4-assembly.3dba', import.meta.url), await writeAssemblyFile({ ...doc, schemaVersion: 4 }));
});

// Schema 5 sample (4a-2): the Schema 4 sample's components and patterns, and a step of the exploded view. Written by the Schema 6 code with schemaVersion set to 5:
// Schema 6 only adds the optional `more`, `min` and `max` of a mate, so a Schema 5 file is exactly this text.
it.skipIf(process.env.WRITE_FIXTURE_V5 !== '1')('writes the version-5 assembly sample', async () => {
  let doc = createEmptyAssembly();
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', file: { id: 'file1', path: '../定位板.3dbx' }, component: { id: 'comp1', file: 'file1', instance: 1, fixed: true, placement: { position: [0, 0, 0], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, { type: 'insertComponent', file: { id: 'file2', path: '../零件/削邊銷.3dbx' }, component: { id: 'comp2', file: 'file2', instance: 1, fixed: false, placement: { position: [-40, 15, 0], rotation: [0, 0, 0, 1] } } });
  doc = applyAssemblyCommand(doc, { type: 'insertMate', mate: { id: 'mate1', name: '結合1', type: 'distance', a: { component: 'comp1', ref: { kind: 'datum', name: 'plane:top' } }, b: { component: 'comp2', ref: { kind: 'datum', name: 'plane:top' } }, align: 'aligned', value: '15', suppressed: false } });
  doc = applyAssemblyCommand(doc, { type: 'insertExplodeStep', step: { id: 'explode1', name: '爆炸步驟1', components: ['comp2'], axis: { kind: 'axis', axis: 'y' }, distance: '30' } });
  writeFileSync(new URL('../../tests/fixtures/old-versions/v5-assembly.3dba', import.meta.url), await writeAssemblyFile({ ...doc, schemaVersion: 5 }));
});

